   [30]={next_id=31, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="大空洞 旧矿道", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="1008", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [31]={next_id=32, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你们沿着来时的旧矿道往回走。这次不走原路，蛰吻说旧矿道有好几个分岔口，其中一条能从东区边缘绕回大空洞主城区，比来时的路更隐蔽。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [32]={next_id=33, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="矿道里依旧昏暗，只有裸露的星彩源晶在岩壁上散发着幽幽的微光。脚下的碎石在靴底下发出细碎的咔嚓声，偶尔有水滴从头顶的岩缝中落下。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [33]={next_id=34, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你的伤……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [34]={next_id=35, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="已经没事了，在影巢里学会控制自己的伤口是必修课，学不会就得死。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [35]={next_id=36, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是吗……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [36]={next_id=37, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你沉默了一会儿。刚才那些记忆还在你脑海里翻涌。影巢、芒刺、那首摇篮曲。你有很多想问的，但你知道现在不是时候。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [37]={next_id=38, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我知道你想说什么，链尉官。放心，我可没那么脆弱。孤儿院的孩子们，还有余烬的大家，他们还在等着我回去呢。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="从我们进入矿道到现在，不知道过去了多久。凯瑞公司已经撕破脸了，每多等一分钟，他们就多一分危险。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="影巢的余党、凯瑞公司的实验室，还有那些水晶花……它们之间的联系，我必须查清楚。但现在，我们必须先回到余烬。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [40]={next_id=41, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="好。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [41]={next_id=42, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="走了大约半个钟头，一切似乎都还算顺利。直到蛰吻突然停下了脚步。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [42]={next_id=43, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [43]={next_id=44, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="怎么了？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [44]={next_id=45, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="有三个人。大约在四十步外，正在朝我们这边移动。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [45]={next_id=46, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你的手已经按在了枪柄上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [46]={next_id=47, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="看来不是偶遇。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [47]={next_id=48, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是伏击，没想到他们反应这么快，竟然在短时间内就摸清所有矿道的路线并且安排了杀手伏击我们。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [48]={next_id=49, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她从腰间拔出短刀。刀锋在源晶的微光下泛着寒芒。她没有多余的话，只是偏头看了你一眼。你点了点头，拔出了配枪。两个人默契地分别退入矿道两侧的岩壁凹处，将自己融入阴影之中。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [49]={next_id=50, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="大约十秒后，脚步声出现了。轻而稳，是训练有素的步伐。三道身影从矿道拐角处走了出来，穿着深色的紧身衣，脸上蒙着统一的黑色面罩。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [50]={next_id=51, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他们的动作警惕而有序，显然不是凯瑞公司那种三流安保能比的。其中一个打头阵的人伸出手，示意身后两人停下。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [51]={next_id=52, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他蹲下身，用手指抹了一下地面，随后放到鼻子上闻了闻。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [52]={next_id=53, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是他们的味道， 还新鲜，没走远。分头搜。", msg_color="", msg_size=0, talker="杀手", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [53]={next_id=54, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="三个杀手分别散开，动作迅速而无声。其中一人正朝你藏身的岩壁凹处走来，距离越来越近……五步，三步，两步。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [54]={next_id=55, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在阴影中，你屏住呼吸，手指稳稳搭在扳机上。那个杀手走到凹处边缘，偏头朝阴影里看过来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [55]={next_id=56, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="砰——", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=1, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [56]={next_id=57, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="枪声在狭窄的矿道里炸开，回声在岩壁间碰撞了数次才消散。那人倒下的瞬间，蛰吻已经从另一侧的阴影中闪出，短刀精准地划过第二个杀手的胸口。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [57]={next_id=58, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="从杀手的胸口里抖出来的一包红色的粉末。粉末散落一地，和刚才在实验室里那蓝色的粉尘很像。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [58]={next_id=59, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="小心那些粉末！", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [59]={next_id=60, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="第三个杀手没有逃跑。他反而后退了一步，从腰间拔出一只金属小盒，猛地捏碎。盒中洒出一团红色的粉尘，细密得像是雾化的血。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [60]={next_id=61, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那粉尘没有飘散，而是被他吸入了鼻腔。他的瞳孔瞬间变成了猩红色，眼白布满了蛛网般的红线。他的身体猛地膨胀了一截，肌肉鼓胀得几乎要撑破衣服，脊椎咔咔作响。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [61]={next_id=62, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这是什么东西？", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [62]={next_id=63, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="好像是某种狂化药剂。但看样子，这种药剂的副作用好像很大，那个杀手几乎都不成人形了。简直就像是……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [63]={next_id=64, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="异变体。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [64]={next_id=65, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="看来这种红色的粉末应该也是那种粉色粉末稀释后的东西，不过要比发给矿工们的绿色浓度要更高。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [65]={next_id=66, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="变成了异变体，他们是不打算活着回去了。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [66]={next_id=67, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="影巢就是这样，只要能完成目标，他们根本就不在乎自己的命。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="狂化的杀手发出一声低沉的咆哮，朝你猛冲过来。速度比之前快了至少两倍，快到你无法精确瞄准。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [68]={next_id=69, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你侧身滚开，他砸在你刚才藏身的岩壁上，碎石四溅。他的拳头嵌进了岩石。没有痛觉，没有停顿，他直接拔出手臂，转身朝你挥出第二击。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [69]={next_id=70, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻从侧面切入，短刀直取他的咽喉。但他的感知似乎也变强了——他甚至没有转头，只是侧移半步就躲开了刀锋。胳膊像铁棍一样扫过去，逼得蛰吻不得不向后翻撤。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [70]={next_id=71, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他的反应速度和力量都大幅提升了。这些粉尘比实验室里那种更危险。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [71]={next_id=72, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻想到黑袍人处处针对自己的手段，想到孤儿院里那些孩子们正在等着自己回去，她的心中有所决断", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [72]={next_id=-1, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="链尉官……和我进行神血链接吧！", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_702.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
